# 1. THUẬT TOÁN LINEAR CHACHA20 
def bytes_to_words(b):
    return [int.from_bytes(b[i:i+_sage_const_4 ], 'little') for i in range(_sage_const_0 , len(b), _sage_const_4 )]

def words_to_bytes(w):
    return b''.join([i.to_bytes(_sage_const_4 , 'little') for i in w])

def rotate(x, n):
    return ((x << n) & _sage_const_0xffffffff ) | ((x >> (_sage_const_32  - n)) & _sage_const_0xffffffff )

def xor_bytes(a, b):
    return bytes([operator.xor(x, y) for x, y in zip(a, b)])

class LinearChaCha20:
    def __init__(self):
        self._state = []
        self._initial_state = [] 

    def _quarter_round(self, x, a, b, c, d):
        x[a] = operator.xor(x[a], x[b]); x[d] = operator.xor(x[d], x[a]); x[d] = rotate(x[d], _sage_const_16 )
        x[c] = operator.xor(x[c], x[d]); x[b] = operator.xor(x[b], x[c]); x[b] = rotate(x[b], _sage_const_12 )
        x[a] = operator.xor(x[a], x[b]); x[d] = operator.xor(x[d], x[a]); x[d] = rotate(x[d], _sage_const_8 )
        x[c] = operator.xor(x[c], x[d]); x[b] = operator.xor(x[b], x[c]); x[b] = rotate(x[b], _sage_const_7 )

    def _inner_block(self, state):
        self._quarter_round(state, _sage_const_0 , _sage_const_4 , _sage_const_8 , _sage_const_12 )
        self._quarter_round(state, _sage_const_1 , _sage_const_5 , _sage_const_9 , _sage_const_13 )
        self._quarter_round(state, _sage_const_2 , _sage_const_6 , _sage_const_10 , _sage_const_14 )
        self._quarter_round(state, _sage_const_3 , _sage_const_7 , _sage_const_11 , _sage_const_15 )
        self._quarter_round(state, _sage_const_0 , _sage_const_5 , _sage_const_10 , _sage_const_15 )
        self._quarter_round(state, _sage_const_1 , _sage_const_6 , _sage_const_11 , _sage_const_12 )
        self._quarter_round(state, _sage_const_2 , _sage_const_7 , _sage_const_8 , _sage_const_13 )
        self._quarter_round(state, _sage_const_3 , _sage_const_4 , _sage_const_9 , _sage_const_14 )

    def _setup_state(self, key, iv):
        self._state = [_sage_const_0x61707865 , _sage_const_0x3320646e , _sage_const_0x79622d32 , _sage_const_0x6b206574 ]
        self._state.extend(bytes_to_words(key))
        self._state.append(self._counter)
        self._state.extend(bytes_to_words(iv))
        self._initial_state = self._state[:] 

    def encrypt(self, m, key, iv):
        c = b''
        self._counter = _sage_const_1 
        for i in range(_sage_const_0 , len(m), _sage_const_64 ):
            self._setup_state(key, iv)

            for j in range(_sage_const_10 ):
                self._inner_block(self._state)

            for k in range(_sage_const_16 ):
                self._state[k] = operator.xor(self._state[k], self._initial_state[k])

            c += xor_bytes(m[i:i+_sage_const_64 ], words_to_bytes(self._state))
            self._counter += _sage_const_1 
        return c

    def decrypt(self, c, key, iv):
        return self.encrypt(c, key, iv)
    


